import importlib.util,json
spec=importlib.util.spec_from_file_location('f','fit.py')
src=open('fit.py').read().split('fits = {}')[0]
g={}; exec(src,g)
for cid in ['C4','C6','C1']:
    S,v,_=g['points'](cid)
    best=None
    for vm in [x*0.001 for x in range(150,320)]:
        for km in [x*1.0 for x in range(20,800,2)]:
            c=sum((vm*s/(km+s)-y)**2 for s,y in zip(S,v))
            if best is None or c<best[0]: best=(c,vm,km)
    print(cid,'grid best Vmax=%.4f Km=%.1f'%(best[1],best[2]))

